#!/usr/bin/env bash
# Local k3d demo of the whole K8s loop (c0034). Touches ONLY cluster finops-test (context k3d-finops-test).
#   pipeline (synthetic world) -> generated plans -> gates -> canary on the demo cluster -> ledger -> weekly report
# Usage: bash scripts/k8s_demo.sh        (or: make k8s-demo)   Tear down: make k8s-down
# The plans are GENERATED by `k8s run` from the synthetic world's shop/api-steady, not written by hand. ops/k3d/shop.yaml
# is made equal to that world's api-steady (3 replicas, container app, cpu 1/2, memory 2Gi/3Gi), so `before` needs no adaptation;
# ops/k3d/adapt_plan.py checks that and, only if they differ, adapts loudly.
set -uo pipefail
cd "$(dirname "$0")/.."

CLUSTER=finops-test
CTX=k3d-finops-test
RUN=runs/k8s-demo
PLANS=$RUN/k8s_plans.json
STATE=$RUN/k8s_state.json
PORT=${K8S_DEMO_PROM_PORT:-19191}
AS_OF=2026-10-26T00:00:00Z
export FINOPS_LLM_MODE=${FINOPS_LLM_MODE:-replay}
rm -rf "$RUN"; mkdir -p "$RUN" runs/approvals
: > "$RUN/demo.log"
rm -f runs/approvals/P-K-shop-api-steady-*.approved
PID=""
trap '[ -n "$PID" ] && { kill "$PID"; wait "$PID"; } 2>/dev/null' EXIT

say() { echo "$*" | tee -a "$RUN/demo.log"; }
step() { say ""; say "=== [$1] $2"; }
# every cluster command names the test context explicitly; writes carry an INTENT line
kc() { kubectl --context "$CTX" "$@"; }
kw() { local why=$1; shift; say "# INTENT: $why"; kc "$@" 2>&1 | tee -a "$RUN/demo.log"; }
act() { python3 -m finops_agent.k8s.act "$@" --state "$STATE" 2>&1 | tee -a "$RUN/demo.log"; return "${PIPESTATUS[0]}"; }
ledger() { python3 -m finops_agent k8s ledger --state "$STATE" "$@" 2>&1 | tee -a "$RUN/demo.log"; }
metrics() { kc get --raw /api/v1/namespaces/shop/services/api-steady:8080/proxy/metrics 2>/dev/null | tr '\n' ' '; }
resources() { kc -n shop get deploy api-steady -o jsonpath='{.spec.template.spec.containers[0].resources}'; }
# set_load <rps per generator> <workers per generator> <generators>
set_load() { kw "set loadgen to $1 rps x $3 generators to drive the canary" -n shop set env deploy/loadgen RPS="$1" WORKERS="$2" >/dev/null
             kw "run $3 load generator(s)" -n shop scale deploy/loadgen --replicas="$3" >/dev/null
             kc -n shop rollout status deploy/loadgen --timeout=120s | tee -a "$RUN/demo.log"; }
plan_of() { python3 - "$PLANS" "$1" <<'PY'
import json, sys
plans = json.load(open(sys.argv[1]))["plans"]
print(next(p["plan_id"] for p in plans if p["decision_id"] == sys.argv[2]))
PY
}

step 1 "create cluster $CLUSTER (idempotent)"
REUSED=0
if k3d cluster list "$CLUSTER" >/dev/null 2>&1; then
  REUSED=1
  say "cluster exists, reusing"; k3d cluster start "$CLUSTER" 2>&1 | tail -1 | tee -a "$RUN/demo.log"
else
  k3d cluster create "$CLUSTER" --servers 1 --agents 0 --no-lb --wait \
    --kubeconfig-switch-context=false 2>&1 | tail -3 | tee -a "$RUN/demo.log"
fi
if docker image inspect python:3.12-alpine >/dev/null 2>&1 || docker pull -q python:3.12-alpine >/dev/null 2>&1; then
  k3d image import python:3.12-alpine -c "$CLUSTER" 2>&1 | tail -1 | tee -a "$RUN/demo.log"
fi
kc get nodes 2>&1 | tee -a "$RUN/demo.log"

step 2 "deploy namespace shop: api-steady (equal to the synthetic world's api-steady) + loadgen"
kw "create the demo workload in the disposable test cluster" apply -k ops/k3d
if [ "$REUSED" = 1 ]; then   # a reused cluster may run an older app.py: restart so the pods read the current one
  kw "restart the demo pods so they pick up the current demo scripts" -n shop rollout restart deploy/api-steady deploy/loadgen
fi
kc -n shop rollout status deploy/api-steady --timeout=240s | tee -a "$RUN/demo.log"
kc -n shop rollout status deploy/loadgen --timeout=180s | tee -a "$RUN/demo.log"
say "resources before: $(resources)"
sleep 10; say "baseline metrics: $(metrics)"

step 3 "k8s run against the synthetic metrics server: decisions, plans, ledger, three reports"
python3 -m testenv.metrics_server --port "$PORT" --world k8s >/dev/null 2>&1 & PID=$!
for _ in $(seq 1 60); do curl -sf "localhost:$PORT/-/healthy" >/dev/null && break; sleep 0.5; done
python3 -m finops_agent k8s run --prom "http://127.0.0.1:$PORT" --slos testenv/k8s_slos.yaml --nodes-from testenv/k8s_world.yaml \
  --as-of "$AS_OF" --run-id k8s-demo --out runs --state "$STATE" --world-label k8s-synth 2>&1 | tee -a "$RUN/demo.log" | grep -v '^runs/'
kill "$PID" 2>/dev/null; wait "$PID" 2>/dev/null; PID=""
CPU_PLAN=$(plan_of K-shop-api-steady-cpu)
MEM_PLAN=$(plan_of K-shop-api-steady-memory)
say "generated plans for shop/api-steady (verdict ALLOW both): $CPU_PLAN  $MEM_PLAN"
python3 - "$RUN" <<'PY' | tee -a "$RUN/demo.log"
import json, sys
d = json.load(open(sys.argv[1] + "/k8s_decisions.json"))["decisions"]
for x in d:
    if x["workload"] == "api-steady":
        print(f"  {x['id']}: {x['verdict']}  {x['current']['request']:g} -> {x['recommendation']['request']:g} {x['current']['unit']}")
PY
kc -n shop get deploy api-steady -o json > "$RUN/live_deploy.json"
say "check: does the demo deployment equal what the plans assumed?"
python3 ops/k3d/adapt_plan.py "$PLANS" "$RUN/live_deploy.json" "$CPU_PLAN" "$MEM_PLAN" 2>&1 | tee -a "$RUN/demo.log"
python3 - "$PLANS" "$CPU_PLAN" "$MEM_PLAN" "$RUN/k8s_plans_wrongctx.json" <<'PY'
import json, sys
doc = json.load(open(sys.argv[1]))
doc["plans"] = [dict(p, context="k3d-wrong-context") for p in doc["plans"] if p["plan_id"] in sys.argv[2:4]]
json.dump(doc, open(sys.argv[4], "w"))
PY
say "--- ledger after the run (nothing is approved yet)"
ledger | grep "shop-api-steady"

step 4 "refusal 1: no approval file"
act apply --plans $PLANS --plan-id "$CPU_PLAN"; say "exit=$? (3 = refused)"

step 5 "refusal 2: wrong context (copy of the plan edited)"
act apply --plans $RUN/k8s_plans_wrongctx.json --plan-id "$CPU_PLAN"; say "exit=$? (3 = refused)"
say "resources unchanged: $(resources)"
say "--- ledger unchanged by refusals"; ledger | grep "shop-api-steady"

step 6 "human approves: create the approval files (the agent never does)"
for P in "$CPU_PLAN" "$MEM_PLAN"; do echo "approved by demo operator $(date -u +%FT%TZ)" > "runs/approvals/$P.approved"; done
ls runs/approvals | tee -a "$RUN/demo.log"

step 7 "overload the service during the canary (2 load generators x 200 rps), apply the MEMORY plan: expect stop condition p99 and rollback"
say "note: the plans only lower REQUESTS. A lower request does not slow this service down on an idle node (and CPU throttling comes from the"
say "      LIMIT, which no plan changes, so the throttle stop condition stays quiet). The guard that fires is p99 > SLO: any regression inside"
say "      the canary window rolls the change back, whatever caused it. The overload is injected to show that; it is not caused by the lower request."
set_load 200 64 2
sleep 20; say "metrics under overload before patch: $(metrics)"
act apply --plans $PLANS --plan-id "$MEM_PLAN"; RC1=$?; say "exit=$RC1 (4 = rolled_back)"
say "resources after rollback: $(resources)"
say "--- ledger"; ledger | grep "shop-api-steady-memory"

step 8 "back to normal load (5 rps), apply the CPU plan: expect verified"
set_load 5 16 1
sleep 20
act apply --plans $PLANS --plan-id "$CPU_PLAN"; RC2=$?; say "exit=$RC2 (0 = verified)"
say "resources after canary: $(resources)"
say "final metrics: $(metrics)"

step 9 "ledger: the proposals that moved, and the actions"
ledger --only-moved
say "--- k8s_actions.jsonl (time, outcome, ledger, reason)"
python3 - "$RUN" <<'PY' | tee -a "$RUN/demo.log"
import json, sys
for l in open(sys.argv[1] + "/k8s_actions.jsonl"):
    r = json.loads(l)
    led = (r.get("ledger") or {}).get("status") or "-"
    print(f"{r.get('finished_at') or r.get('applied_at')}  {r['plan_id']:<34} {r['outcome']:<11} ledger={led:<11} {r['reason'][:80]}")
PY

step 10 "render the reports again, now with the real k8s_actions.jsonl"
for V in daily weekly monthly; do
  python3 -m finops_agent.k8s.report --run $RUN --state $STATE --view $V --out $RUN/k8s_$V.html
done
say "wrote $RUN/k8s_daily.html $RUN/k8s_weekly.html $RUN/k8s_monthly.html"

step 11 "summary"
if [ "$RC1" = 4 ] && [ "$RC2" = 0 ]; then say "DEMO OK: refusals, rollback and verified path all behaved; the ledger followed"; exit 0; fi
say "DEMO UNEXPECTED: rollback rc=$RC1 success rc=$RC2"; exit 1
